<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> f </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> *.pdf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> *.xlsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> *.pptx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> *.docx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span></span>
